from interops.libraries.desktop.configuration import Config
import interops.libraries.desktop.config_constants as cfg
import logging
import os
import sys

# Get the current python installation path
python_install_path = sys.exec_prefix
sharedconfig_path = os.path.abspath(os.path.join(
    python_install_path, cfg.DEFAULT_SHAREDCONFIG_PATH))
# Load the sharedconfig.cfg file
Config.load(sharedconfig_path)
squish_bin_path = Config.get("system.squish_bin", cfg.DEFAULT_DEV_SQUISH_BIN_PATH)
squish_python_lib_path = Config.get("system.squish_python_lib", cfg.DEFAULT_DEV_SQUISH_LIB_PATH)
sys.path.extend([squish_bin_path, squish_python_lib_path])

import squishtest3 as sq
import test
from remotesystem import RemoteSystem

logger = logging.getLogger(__name__)


# Cleanup method to close unwanted apps
def close_open_apps(list_of_apps=["Crowbar", "AgilityHeadSim"], all=False):
    if len(sq.applicationContextList()) == 0:
        logger.debug("No apps found in context list, nothing to close")
        return
    elif all:
        closed = [app.detach() for app in sq.applicationContextList()]
        test.verify(len(sq.applicationContextList()) == 0, "All apps detached from") #type:ignore
    else:
        for app in list_of_apps:
            for app_index in sq.applicationContextList():
                if app == app_index.name:
                    app_index.detach()
                    test.verify(app not in sq.applicationContextList(), "{} closed".format(app)) #type:ignore
